/*
 * A254961  Cubes not divisible by 10 with digits d_1, d_2, ... d_k such that
 *          d_1^3 + ... + d_k^3 is a cube.
 * https://oeis.org/A254961
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 2, u32 n <= 12, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Sequence A254961: the nth cube m³ (m ≥ 1, 10∤m³) whose decimal digits
 * satisfy Σ(dᵢ³) is a perfect cube.  The sequence is generated by
 * testing successive integers m, computing m³, checking the last digit of
 * the cube, summing the cubes of its decimal digits, and verifying that
 * this sum is a cube.  The result is stored in an expanding static cache,
 * so subsequent calls for any index are answered in O(1) after the
 * necessary pre‑computation.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* static state -------------------------------------------------------- */
    static idx_t  max_n     = 0;           /* number of terms computed so far */
    static idx_t  next_m    = 1;           /* next integer to test (m) */
    static seq_t *cache     = NULL;        /* array of cubes found           */
    static size_t cache_cap = 0;           /* current capacity of cache      */

    /* pre‑compute until we have the nth term -------------------------------- */
    while (max_n < n) {
        /* compute cube = next_m³ */
        seq_t cube = (seq_t)next_m;
        cube *= next_m;
        cube *= next_m;

        /* ignore cubes divisible by 10 */
        if ((cube % 10) != 0) {
            /* sum of cubes of decimal digits of cube */
            seq_t tmp = cube;
            uint64_t sum = 0;
            while (tmp > 0) {
                int d = (int)(tmp % 10);
                sum += (uint64_t)d * d * d;
                tmp /= 10;
            }

            /* test whether sum is a perfect cube */
            uint64_t c = 0;
            while ((c + 1) * (c + 1) * (c + 1) <= sum) {
                ++c;
            }
            if (c * c * c == sum) {
                /* store cube in cache */
                if (max_n >= cache_cap) {
                    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                    seq_t *tmp_ptr = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                    if (!tmp_ptr) {                     /* allocation failed */
                        abort();
                    }
                    cache      = tmp_ptr;
                    cache_cap  = new_cap;
                }
                cache[max_n] = cube;
                ++max_n;
            }
        }

        /* advance to next integer */
        ++next_m;
    }

    /* return the requested term -------------------------------------------- */
    return cache[n - 1];
}
